func (b *Backend) configureAutoScaling(status tableStatus, billingMode string) {
	if status == tableStatusOK && billingMode == dynamodb.BillingModePayPerRequest {
		b.disableAutoScaling("table is on-demand")
	} else if status == tableStatusMissing && b.BillingMode == billingModePayPerRequest {
		b.disableAutoScaling("table will be on-demand")
	}
}

func (b *Backend) disableAutoScaling(reason string) {
	if b.EnableAutoScaling {
		b.Infof("auto_scaling is ignored because the %s.", reason)
		b.EnableAutoScaling = false
	}
}

